`timescale 1ns / 1ps
`include "params.vh"
`include "data_dir.vh"   // defines DATA_DIR: absolute path to rtl/ on THIS machine.
                         // Generated by scripts/create_project.tcl (not committed).
// ============================================================================
// layer2.v -- output layer: 32 int8 hidden values -> 10 int32 class scores
//
// Same broadcast pattern as layer1.v, at a smaller size: 10 MACs, one per
// output class. Each clock, ONE hidden value h[j] goes to all 10 MACs while
// an 80-bit weight word gives each MAC its own weight for that hidden unit.
//
//   h[j]     ----+------+-- ... --+
//                |      |         |
//   w2_t[j]  -> MAC0   MAC1  ...  MAC9     (byte n -> MAC n)
//                |      |         |
//             score0 score1 ... score9     (raw int32: no ReLU, no requantize)
//
// There is no requantize here: argmax only needs to compare the scores, and
// comparing is unaffected by any common scale factor.
//
// Interface
//   start     pulse for one cycle while idle. Ignored while busy.
//   h_flat    32 int8 hidden values (neuron j in bits [8j+7:8j]). Must stay
//             stable from start until done -- layer1 holds its output, so
//             wiring layer1.h_flat here directly is safe.
//   done      one-cycle pulse. scores_flat valid from then until next start.
//   scores_flat  10 int32 scores, class n in bits [32n+31:32n].
//
// Latency: 34 cycles from start to done (32 hidden values + 2).
// The pipeline is cycle-for-cycle identical to layer1.v with N_IN = 32; the
// hidden value is registered on its way in so it arrives with the same
// one-cycle latency a block-RAM pixel has in layer 1.
// ============================================================================

module layer2 (
    input  wire                         clk,
    input  wire                         rst,
    input  wire                         start,
    output reg                          busy,
    output reg                          done,
    input  wire [`N_HIDDEN*8-1:0]       h_flat,
    output wire [`N_OUT*`ACC_W-1:0]     scores_flat
);

    localparam N_IN  = `N_HIDDEN;   // 32 inputs to this layer
    localparam N_O   = `N_OUT;      // 10 classes
    localparam ACC_W = `ACC_W;

    // ------------------------------------------------------------ memories
    // 32 words x 80 bits: small enough that Vivado will use LUTs, not BRAM.
    reg [N_O*8-1:0] w_rom [0:N_IN-1];
    reg [N_O*8-1:0] w_word;
    reg [ACC_W-1:0] bias  [0:N_O-1];

    initial begin
        $readmemh({`DATA_DIR, "w2_t.mem"}, w_rom);
        $readmemh({`DATA_DIR, "b2.mem"},   bias);
    end

    reg [4:0] h_addr;               // 0..31
    reg [7:0] h_q;                  // h[h_addr], one cycle later

    always @(posedge clk) begin
        w_word <= w_rom[h_addr];
        h_q    <= h_flat[8*h_addr +: 8];
    end

    // ------------------------------------------------------------ control
    // Identical structure to layer1.v -- see that file for the edge-by-edge
    // pipeline description.
    localparam S_IDLE  = 2'd0,
               S_RUN   = 2'd1,
               S_FLUSH = 2'd2,
               S_OUT   = 2'd3;

    reg [1:0] state;
    reg       issue;
    reg       mac_load;
    reg       mac_en;

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            issue    <= 1'b0;
            mac_load <= 1'b0;
            mac_en   <= 1'b0;
            busy     <= 1'b0;
            done     <= 1'b0;
            h_addr   <= 5'd0;
        end else begin
            done     <= 1'b0;
            mac_load <= 1'b0;
            mac_en   <= issue;

            case (state)
                S_IDLE: if (start) begin
                    busy     <= 1'b1;
                    mac_load <= 1'b1;
                    issue    <= 1'b1;
                    h_addr   <= 5'd0;
                    state    <= S_RUN;
                end

                S_RUN: if (h_addr == N_IN - 1) begin
                    issue <= 1'b0;
                    state <= S_FLUSH;
                end else begin
                    h_addr <= h_addr + 5'd1;
                end

                S_FLUSH: state <= S_OUT;

                S_OUT: begin
                    busy  <= 1'b0;
                    done  <= 1'b1;
                    state <= S_IDLE;
                end
            endcase
        end
    end

    // ------------------------------------------------------------ MAC array
    genvar n;
    generate
        for (n = 0; n < N_O; n = n + 1) begin : g_mac
            mac #(.ACC_W(ACC_W)) u_mac (
                .clk  (clk),
                .load (mac_load),
                .en   (mac_en),
                .a    (h_q),                // same hidden value to every MAC
                .b    (w_word[8*n +: 8]),   // this class's weight
                .init (bias[n]),
                .acc  (scores_flat[ACC_W*n +: ACC_W])
            );
        end
    endgenerate

endmodule
